/**
 * Remotion root of a video's thumbnail project (workspace/<ID>/07-publish/remotion/).
 * One still per variant ("TA", "TB", "TC": 1920x1080, drawn by thumbs/<V>.tsx with the Briefing kit) and the two preview sheets.
 * registry.ts is generated by thumbs.ts from the files in thumbs/; this file is synced from workflow/07-publish/template/.
 */
import React from "react";
import { Still } from "remotion";
import { THUMBS } from "./registry";
import { Preview, PreviewSmall, PREVIEW_H, PREVIEW_SMALL, PREVIEW_W, type PreviewProps } from "./Preview";

const empty: PreviewProps = { packages: [], duration: "0:00", channel: "The Wealth Gap" };

export const RemotionRoot: React.FC = () => (
  <>
    {Object.entries(THUMBS).map(([id, Component]) => <Still key={id} id={`T${id}`} component={Component} width={1920} height={1080} />)}
    <Still id="Preview" component={Preview} width={PREVIEW_W} height={PREVIEW_H} defaultProps={empty} />
    <Still id="PreviewSmall" component={PreviewSmall} width={PREVIEW_SMALL.w} height={PREVIEW_SMALL.h} defaultProps={empty} />
  </>
);
